/**
 * /status/ —— 服务组件与事件处理说明页
 *
 * 🔴 **这不是一块实时状态看板，页面自己也这么说**。理由：实时看板要有真源与写入者，
 *    我们没有一套对外发布状态的流程；摆一个永远显示「正常」的红绿灯，比没有更糟 ——
 *    它会在真出事的那天替我们撒谎。所以本页只写**有两件事可核**的内容：
 *    ① 有哪些组件（每个组件都在做一件事）；② 出问题时你从哪知道。
 *
 * 🔴 **对外产物纪律**：本页**不写**任何内部端点路径、主机名、仓名或运维细节
 *    （那些属内部信息，见 MEMORY.md §0-C）。
 *
 * @author 恒哥
 * @since 2026-10-13
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import { SUPPORT_EMAIL } from '../constants/brand';
import '../styles/marketing.css';
import T from '../i18n/LocalizedText';
import { usePageI18n } from '../i18n';

const COMPONENTS = [
  {
    name: 'Marketing site',
    what: 'This website — product pages, guides, help articles and the console entry point.',
    note: 'Static pages served from a CDN. If you can read this, it is up.',
  },
  {
    name: 'Console',
    what: 'The authenticated area where connections, keys, suppression and logs are managed.',
    note: 'Availability depends on the API below, because the console reads and writes through it.',
  },
  {
    name: 'Send API',
    what: 'The HTTP interface your own services call to send messages.',
    note: 'Authentication failures and validation errors are returned by the API rather than hidden — a rejection is a response, not an outage.',
  },
  {
    name: 'Delivery receipts',
    what: 'Provider receipts collected and normalized into a single status, on every channel whose provider reports delivery back.',
    note: 'Receipt arrival depends on the provider and the destination network; a missing receipt is not the same as a failed send.',
  },
  {
    name: 'Callback delivery',
    what: 'Receipt events pushed to the endpoint you configure.',
    note: 'Treated as best-effort rather than guaranteed. Reconcile against the message log.',
  },
  {
    name: 'Message logs',
    what: 'The record of what was sent, to whom, with which status.',
    note: 'The authoritative answer to “did we send it?” — read it rather than guessing.',
  },
];

export default function StatusPage(pageContext) {
  const { locale, localePath } = usePageI18n(pageContext);

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title="Service status and incident handling"
        description="What components make up Whaleal Platform, how each one fails, and where to hear from us when something goes wrong."
        pathname="/status/"
        softwareApp={false} hrefLang={locale}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow"><T id="status.001">Status</T></span>
          <h1><T id="status.002">Components, and how we handle an incident</T></h1>
          <p className="mk-lead"><T id="status.003">
            What each component does, how it fails, and where a change is announced — plus the
            fastest way to get an answer when something looks wrong.
          </T></p>
        </header>

        <section className="mk-section">
          <h2><T id="status.004">Components</T></h2>
          <div className="mk-grid">
            {COMPONENTS.map((c) => (
              <article className="mk-card" key={c.name}>
                <h3>{c.name}</h3>
                <p>{c.what}</p>
                <p>{c.note}</p>
              </article>
            ))}
          </div>
        </section>

        <section className="mk-section">
          <h2><T id="status.005">How a problem is normally found</T></h2>
          <p className="mk-section-lead"><T id="status.006">
            Each component exposes a health signal that our own monitoring checks, so a failure is
            usually detected before it is reported. If you saw it first, that is worth telling us —
            it means a signal we rely on needs tightening.
          </T></p>
        </section>

        <section className="mk-section">
          <h2><T id="status.007">Where changes are announced</T></h2>
          <p className="mk-section-lead"><T id="status.008">
            When something ships that changes how the platform behaves, it is written up in the{' '}
            <Link to={localePath("/changelog/")}>changelog</Link> with a date. If you believe something is broken
            now, contact <a href={`mailto:${SUPPORT_EMAIL}`}>{SUPPORT_EMAIL}</a> and include the
            message reference or the time window — the message log is the fastest route to an
            answer, so a reference shortens the loop considerably.
          </T></p>
        </section>

        <div className="mk-scope">
          <T id="status.009"><strong>Scope.</strong> This page describes the components of Whaleal Platform and how
          incidents are handled. It publishes no uptime percentage — if you need one for a
          procurement review, ask us and we will give you what we have.
        </T></div>
      </div>
    </Layout>
  );
}
